// Generated data. DO NOT EDIT BY HAND.
//
// Code point ranges for the predicates the checker's matching rules are
// specified in terms of — `IsSpace`, `IsLetter`, `IsDigit` and `IsPrint` — plus
// the simple `ToLower` mapping. Zig's standard library does not carry this
// data, so it lives here as committed source and `gostd.zig` reads it directly.
//
// Only code points >= 0x80 are tabulated; callers handle ASCII inline.
//
// The ranges were produced by enumerating every code point from 0x80 to
// 0x10FFFF and recording the result of Go 1.27's `unicode.IsSpace`,
// `unicode.IsLetter`, `unicode.IsDigit`, `unicode.IsPrint` and
// `unicode.ToLower`, then merging adjacent code points into ranges. Deriving
// them that way rather than by hand is what makes this checker's Unicode
// behaviour exact, and it is how they should be refreshed for a newer Unicode
// revision: enumerate the same five predicates over the same range from a
// reference implementation, emit `Range` and `CaseMapping` literals in
// ascending order, and run `zig fmt` over the result. The counts at the time of
// writing were 8 space ranges, 682 letter, 71 digit, 740 print, and 1462 lower
// mappings; a refresh should land in the same ballpark.

pub const Range = struct { lo: u21, hi: u21 };

pub const CaseMapping = struct { from: u21, to: u21 };

fn inRanges(ranges: []const Range, r: u21) bool {
    var lo: usize = 0;
    var hi: usize = ranges.len;
    while (lo < hi) {
        const mid = lo + (hi - lo) / 2;
        const entry = ranges[mid];
        if (r < entry.lo) {
            hi = mid;
        } else if (r > entry.hi) {
            lo = mid + 1;
        } else {
            return true;
        }
    }
    return false;
}

